/**
 * Webview Library Shim Source
 *
 * This module exports the shim code that is injected into H5 game WebViews.
 * The actual shim code is in webviewLibraryShim.js and imported as a raw string.
 *
 * Using Vite's ?raw import allows us to:
 * - Keep the shim as actual JavaScript (not a string literal)
 * - Get proper IDE support (syntax highlighting, linting)
 * - Avoid escaping issues
 */
declare const WEBVIEW_LIBRARY_SHIM_SOURCE: string;
declare function getWebviewLibraryShimSource(): string;

export { WEBVIEW_LIBRARY_SHIM_SOURCE, getWebviewLibraryShimSource };
